// Characterization tests: pin the current client-visible behaviour of the HTTP API,
// including quirks (e.g. 200 for unknown order). Do not "fix" these during a restructure.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 2.5, C: 0.3, BIG: 200 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('creates an order: 201, JSON, string id, echoed items, total', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /application\/json/)
  const order = await res.json()
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order.items, [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }])
  assert.equal(order.total, 25)
  assert.deepEqual(Object.keys(order).sort(), ['id', 'items', 'total'])
})

test('ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total is floored to an integer', async () => {
  const order = await (await post({ items: [{ sku: 'B', qty: 3 }] })).json() // 7.5
  assert.equal(order.total, 7)
})

test('no discount at exactly 100', async () => {
  const order = await (await post({ items: [{ sku: 'A', qty: 10 }] })).json()
  assert.equal(order.total, 100)
})

test('10% discount when total is over 100', async () => {
  const order = await (await post({ items: [{ sku: 'A', qty: 11 }] })).json() // 110 -> 99
  assert.equal(order.total, 99)
  const big = await (await post({ items: [{ sku: 'BIG', qty: 1 }] })).json() // 200 -> 180
  assert.equal(big.total, 180)
})

test('discount applied before flooring', async () => {
  const order = await (await post({ items: [{ sku: 'A', qty: 10 }, { sku: 'C', qty: 1 }] })).json() // 100.3 -> 90.27
  assert.equal(order.total, 90)
})

test('GET returns a created order', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 with error body (not 404)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'x' }],
  ['empty body', undefined, ''],
  ['invalid JSON', undefined, '{nope'],
]) {
  test(`POST rejects ${name} with 400`, async () => {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  })
}

test('unknown routes and methods return 404 no route', async () => {
  for (const [method, path] of [['GET', '/nope'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['PUT', '/orders'], ['GET', '/orders/1/extra']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
